TYPE E_FB_State : (IDLE, MOVING, WAIT_PROCESS, DONE) END_TYPE
END_TYPE

FUNCTION_BLOCK FB
VAR_INPUT
    processLength : USINT;
    sensor1 : BOOL;
    sensor2 : BOOL;
    sensor3 : BOOL;
    sensor4 : BOOL;
    sensor5 : BOOL;
    station1Start : BOOL;
    station2Complete : BOOL;
    station3Complete : BOOL;
    station4Complete : BOOL;
    processSequence : ARRAY[1..8] OF USINT;
END_VAR
VAR_OUTPUT
    conveyorLeft : BOOL;
    conveyorRight : BOOL;
END_VAR
VAR
    state : E_FB_State := IDLE;
    currentStation : USINT := 1;
    seqIndex : USINT := 1;
    targetStation : USINT := 5;
    lastStation1Start : BOOL := FALSE;
    lastComplete2 : BOOL := FALSE;
    lastComplete3 : BOOL := FALSE;
    lastComplete4 : BOOL := FALSE;
END_VAR

(* 默认输出 *)
conveyorLeft := FALSE;
conveyorRight := FALSE;

(* 检查 processLength 有效性 *)
IF (processLength < 1) OR (processLength > 8) THEN
    state := IDLE;
    currentStation := 1;
    seqIndex := 1;
    (* 输出保持 FALSE *)
ELSE
    (* 状态转移 *)
    IF (state = IDLE) OR (state = DONE) THEN
        (* 检测启动上升沿，需 sensor1 有料 *)
        IF (NOT lastStation1Start AND station1Start AND sensor1) THEN
            seqIndex := 1;
            currentStation := 1;
            targetStation := processSequence[1];
            state := MOVING;
        END_IF
    ELSIF state = MOVING THEN
        (* 检测是否到达目标站 *)
        CASE targetStation OF
            2: IF sensor2 THEN
                   currentStation := targetStation;
                   IF targetStation = 5 THEN
                       state := DONE;
                   ELSE
                       state := WAIT_PROCESS;
                   END_IF
               END_IF
            3: IF sensor3 THEN
                   currentStation := targetStation;
                   IF targetStation = 5 THEN
                       state := DONE;
                   ELSE
                       state := WAIT_PROCESS;
                   END_IF
               END_IF
            4: IF sensor4 THEN
                   currentStation := targetStation;
                   IF targetStation = 5 THEN
                       state := DONE;
                   ELSE
                       state := WAIT_PROCESS;
                   END_IF
               END_IF
            5: IF sensor5 THEN
                   currentStation := targetStation;
                   state := DONE;
               END_IF
        END_CASE
    ELSIF state = WAIT_PROCESS THEN
        (* 检测加工完成上升沿 *)
        IF (currentStation = 2 AND (NOT lastComplete2 AND station2Complete)) OR
           (currentStation = 3 AND (NOT lastComplete3 AND station3Complete)) OR
           (currentStation = 4 AND (NOT lastComplete4 AND station4Complete)) THEN
            seqIndex := seqIndex + 1;
            IF seqIndex <= processLength THEN
                targetStation := processSequence[seqIndex];
                state := MOVING;
            ELSE
                state := DONE;
            END_IF
        END_IF
    END_IF

    (* 根据最终状态设置输出 *)
    IF state = MOVING THEN
        IF targetStation > currentStation THEN
            conveyorLeft := FALSE;
            conveyorRight := TRUE;
        ELSIF targetStation < currentStation THEN
            conveyorLeft := TRUE;
            conveyorRight := FALSE;
        ELSE
            conveyorLeft := FALSE;
            conveyorRight := FALSE;
        END_IF
    ELSE
        conveyorLeft := FALSE;
        conveyorRight := FALSE;
    END_IF
END_IF

(* 更新边沿历史 *)
lastStation1Start := station1Start;
lastComplete2 := station2Complete;
lastComplete3 := station3Complete;
lastComplete4 := station4Complete;

END_FUNCTION_BLOCK
